}
function foldCompletedCollections(obj){
 const keys=Object.keys(obj);
 const groups=[
  {item:/(TASK|TAREA)/,done:/(COMPLETED|COMPLETAD|DONE|FINISHED|FINALIZAD)/,active:/(^TASKS?$|^TAREAS?$|ACTIVE|ACTIVAS?)/},
