.v27-hub-button.task{border-color:rgba(0,225,246,.68)!important;background:linear-gradient(130deg,#063449,#061635 85%)!important}
.v27-hub-button.habit b{color:#fff6e7!important}.v27-hub-button.task b{color:#f3fcff!important}
.v27-hub-button .v30-hub-icon{filter:drop-shadow(0 0 9px rgba(0,234,255,.35))}
.v27-hub-button.habit .v30-hub-icon{filter:drop-shadow(0 0 9px rgba(255,187,55,.36))}
/* Grupos de hábitos y tareas — tarjetas en dos columnas como las referencias. */
.kpi-grid.v27-habit-kpis,.kpi-grid.v27-task-kpis{grid-template-columns:repeat(2,minmax(0,1fr))!important;gap:10px!important}
.kpi-grid.v27-habit-kpis::before,.kpi-grid.v27-task-kpis::before{font-weight:900!important;letter-spacing:1px!important;text-shadow:0 0 10px currentColor}
.kpi-grid.v27-habit-kpis::before{color:#ffbb55!important}
.kpi-grid.v27-task-kpis::before{color:#38e7fa!important}
.kpi-grid.v27-habit-kpis .kpi-card,.kpi-grid.v27-task-kpis .kpi-card{border-radius:17px!important;min-width:0!important;background:linear-gradient(145deg,rgba(1,44,59,.97),rgba(6,19,48,.98))!important;border:1px solid rgba(0,214,241,.64)!important;box-shadow:inset 0 1px 0 rgba(67,247,255,.09),0 0 13px rgba(0,176,246,.10)!important}
.kpi-grid.v27-habit-kpis .kpi-card:first-child{background:radial-gradient(circle at 12% 0,rgba(255,145,46,.27),transparent 60%),linear-gradient(145deg,#27201f,#121327)!important;border-color:rgba(255,183,65,.72)!important;box-shadow:0 0 15px rgba(255,153,48,.13),inset 0 1px 0 rgba(254,197,95,.12)!important}
.kpi-grid.v27-habit-kpis .kpi-card:last-child,.kpi-grid.v27-task-kpis .kpi-card:last-child{background:linear-gradient(120deg,#052a37,#071746 90%)!important;border-color:rgba(23,184,255,.72)!important}
.kpi-grid.v27-habit-kpis .kpi-card:first-child .kpi-value{color:#ffd064!important;text-shadow:0 0 13px rgba(255,170,62,.22)}
.kpi-grid .kpi-card .kpi-value{color:#23def5!important;text-shadow:0 0 12px rgba(25,229,251,.26)}
.kpi-grid .kpi-card .kpi-label{color:#acb8d7!important;text-transform:uppercase;letter-spacing:.025em!important}
.kpi-grid .kpi-icon{border-radius:12px!important;background:linear-gradient(145deg,rgba(0,203,244,.22),rgba(20,93,172,.16))!important;filter:drop-shadow(0 0 5px rgba(8,232,252,.17))}
.kpi-grid.v27-habit-kpis .kpi-card:first-child .kpi-icon{background:linear-gradient(130deg,rgba(255,151,50,.28),rgba(108,48,41,.17))!important}
/* Racha global: degradado violeta / ámbar con bisel de luz. */
.v28-streak-card{isolation:isolate!important;border-radius:19px!important;border:1px solid rgba(183,66,255,.72)!important;background:radial-gradient(circle at 3% 14%,rgba(129,26,216,.35),transparent 44%),radial-gradient(circle at 98% 5%,rgba(255,142,38,.30),transparent 36%),linear-gradient(145deg,#19102b,#0c1637 75%,#180e2d)!important;box-shadow:0 0 18px rgba(131,59,245,.18),inset 0 0 18px rgba(194,42,240,.07)!important}
.v28-streak-eyebrow{color:#ffe078!important;text-shadow:0 0 8px rgba(255,176,65,.20)!important}
.v28-streak-value>span,.v28-streak-best strong{color:#ffcf5a!important;text-shadow:0 0 11px rgba(255,182,60,.20)}
.v28-streak-note{color:#bec7e0!important}
.v28-streak-best{background:linear-gradient(105deg,rgba(255,202,92,.095),rgba(53,56,125,.20))!important;border:1px solid rgba(186,145,253,.27)!important;border-radius:12px!important}
/* Análisis de disciplina — panel translúcido y celdas iluminadas. */
.dashboard.v48-discipline-center{border-radius:19px!important;background:radial-gradient(circle at 0 0,rgba(3,158,202,.20),transparent 45%),linear-gradient(150deg,#06192e,#070e22)!important;border:1px solid rgba(13,171,237,.60)!important;box-shadow:0 0 15px rgba(1,181,246,.11),inset 0 1px 0 rgba(61,197,253,.08)!important}
.v48-dashboard-title .v48-title-icon{background:linear-gradient(130deg,#035f70,#082b59)!important;color:#2befff!important;box-shadow:0 0 12px rgba(0,225,254,.12)}
.v48-dashboard-title strong{color:#f7fbff!important}
.v48-dashboard-title small,.v48-card-head small{color:#a4b0d0!important}
.v48-week-card,.v48-analysis-grid article,.v48-week-strip>*{background:linear-gradient(145deg,rgba(11,32,58,.98),rgba(11,20,43,.95))!important;border:1px solid rgba(53,111,177,.28)!important;border-radius:12px!important}
.v48-analysis-grid article{box-shadow:inset 0 1px 0 rgba(39,178,231,.06)!important}
/* Menú desplegable: conservar los elementos reales y la funcionalidad de navegación. */
.side-menu{background:radial-gradient(ellipse at 90% 0,rgba(13,138,194,.15),transparent 48%),linear-gradient(155deg,#050e1e,#07152d 70%,#061329)!important;border-right:2px solid rgba(0,228,255,.88)!important;box-shadow:14px 0 32px rgba(0,6,25,.7),2px 0 17px rgba(6,223,254,.28)!important;backdrop-filter:blur(12px)}
.side-menu.open{box-shadow:18px 0 48px rgba(0,2,15,.78),2px 0 21px rgba(0,223,252,.38)!important}
.menu-overlay{background:rgba(1,6,20,.62)!important;backdrop-filter:blur(4px)}
.menu-header{position:relative!important;overflow:hidden!important;padding-top:24px!important;padding-bottom:22px!important;background:radial-gradient(ellipse at 100% 0,rgba(6,225,246,.12),transparent 55%),linear-gradient(120deg,#08182c,#061328)!important;border-bottom:1px solid rgba(0,213,246,.31)!important}
.menu-header::before{content:"";position:absolute;inset:-45% -35% auto auto;width:65%;aspect-ratio:1;border-radius:50%;border:1px solid rgba(0,219,249,.30);box-shadow:0 0 0 22px rgba(10,166,235,.025),0 0 30px rgba(5,213,247,.06);pointer-events:none}
.menu-header h2{font-size:clamp(22px,5vw,29px)!important;font-weight:900!important}
.menu-header p{color:#98aace!important;font-size:11px!important}
.quick-actions-title,.menu-section-label{color:#a4b1d6!important;letter-spacing:1.2px!important;font-size:10px!important;font-weight:850!important}
.quick-actions-grid,.tf-v91-actions-grid{display:grid!important;grid-template-columns:repeat(2,minmax(0,1fr))!important;gap:10px!important}
.quick-action-btn{position:relative!important;min-height:92px!important;display:flex!important;flex-direction:column!important;gap:7px!important;border-radius:15px!important;border:1px solid rgba(2,211,252,.70)!important;color:#f3faff!important;background:linear-gradient(140deg,rgba(3,51,76,.96),rgba(10,24,61,.98))!important;box-shadow:0 0 16px rgba(0,178,242,.13),inset 0 1px 0 rgba(88,237,252,.08)!important;white-space:normal!important;text-align:center!important}
.quick-action-btn:nth-child(even){background:radial-gradient(circle at 95% 5%,rgba(255,163,57,.19),transparent 55%),linear-gradient(140deg,#181b34,#0b1730)!important;border-color:rgba(255,157,66,.63)!important;box-shadow:0 0 14px rgba(255,128,30,.11)!important}
.quick-action-btn .quick-action-icon{display:grid!important;place-items:center!important;border-radius:12px!important;background:linear-gradient(130deg,#034657,#092f55)!important;border:1px solid rgba(28,229,251,.27)!important;box-shadow:0 0 12px rgba(0,207,241,.12)!important}
.quick-action-btn:nth-child(even) .quick-action-icon{background:linear-gradient(145deg,#543225,#2a2130)!important;color:#ffb05a!important;border-color:rgba(255,179,72,.34)!important}
.menu-items{padding:12px!important}
.v27-menu-hub,.menu-item{border-radius:13px!important;border:1px solid rgba(30,169,239,.45)!important;background:linear-gradient(125deg,rgba(5,45,65,.89),rgba(11,24,66,.89))!important;box-shadow:inset 0 1px 0 rgba(80,215,250,.065),0 0 11px rgba(14,143,235,.065)!important;color:#eef8ff!important}
.v27-menu-hub.habit,.v27-menu-hub.habit-category{border-color:rgba(8,219,242,.48)!important}
.v27-menu-hub.task,.v27-menu-hub.task-category{border-color:rgba(49,126,255,.48)!important}
.v27-menu-hub .menu-icon,.menu-item .menu-icon{background:linear-gradient(135deg,rgba(2,191,213,.23),rgba(36,109,201,.15))!important;border-radius:12px!important}
/* Movimiento tenue: no sobrecargar el teléfono ni interferir en eventos. */
@keyframes tf108TimeGlow{from{filter:brightness(.95);opacity:.86}to{filter:brightness(1.22);opacity:1}}
@media(hover:hover) and (prefers-reduced-motion:no-preference){.kpi-card:hover,.v27-hub-button:hover,.v27-menu-hub:hover,.quick-action-btn:hover{filter:saturate(1.12) brightness(1.08);box-shadow:0 0 22px rgba(0,216,254,.18)!important}}
@media(prefers-reduced-motion:reduce){.reset-countdown-time::after{animation:none!important}}
@media(max-width:620px){.top-bar{padding:10px 12px!important;gap:8px!important}.wrap{padding:10px 12px!important}.reset-countdown-card{margin-bottom:12px!important;padding:15px 15px!important}.reset-countdown-time{font-size:clamp(37px,10vw,58px)!important}.v28-streak-card{margin-bottom:12px!important}.kpi-grid.v27-habit-kpis,.kpi-grid.v27-task-kpis{gap:8px!important}.kpi-grid.v27-habit-kpis .kpi-card,.kpi-grid.v27-task-kpis .kpi-card{min-height:92px!important;aspect-ratio:auto!important}.side-menu{width:min(86vw,330px)!important}.side-menu:not(.open){left:-105vw!important}.side-menu.open{left:0!important}}
@media(max-width:340px){.wrap{padding:8px!important}.reset-countdown-time{font-size:35px!important}.kpi-grid.v27-habit-kpis,.kpi-grid.v27-task-kpis{gap:7px!important}.quick-action-btn{min-height:83px!important}}
